import { parseCsvLine, CsvError } from "/private/var/folders/pv/m1k13gmn189d64ndtxdbzrjc0000gn/T/grooph-compare-red-team-loop-C-k91gKG/src/csv.mjs";
import { oracle } from "./oracle.mjs";

const alphabet = ['"', ",", "\n", "\r", "a", "b", " ", "\t", "\0", "﻿", " ", "\u0085", "\uD800", "\uDC00", "é", "😀"];
const weighted = ['"', '"', '"', ",", ",", "\n", "\r", "a", "a", " ", "\t", " ", "\uD800", "\0"];
let seed = Number(process.argv[2] ?? 1);
function rnd() { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x7fffffff; }

function run(text) {
  let actual;
  try {
    const r = parseCsvLine(text);
    if (!Array.isArray(r)) return `not array: ${typeof r}`;
    if (Object.getPrototypeOf(r) !== Array.prototype) return "array with wrong prototype";
    if (Object.keys(r).length !== r.length) return "array has holes/extra props";
    for (let k = 0; k < r.length; k++) if (typeof r[k] !== "string") return `field ${k} not a primitive string`;
    if (Object.isFrozen(r)) return "frozen array";
    actual = { ok: true, fields: r };
  } catch (e) {
    if (!(e instanceof CsvError)) return `threw non-CsvError: ${e && e.constructor && e.constructor.name}: ${e && e.message}`;
    if (!(e instanceof Error)) return "CsvError not instanceof Error";
    if (e.name !== "CsvError") return `CsvError name is ${e.name}`;
    actual = { ok: false };
  }
  const exp = oracle(text);
  if (exp.ok !== actual.ok) return `ok mismatch: expected ${exp.ok ? JSON.stringify(exp.fields) : "CsvError"}, got ${actual.ok ? JSON.stringify(actual.fields) : "CsvError"}`;
  if (exp.ok && JSON.stringify(exp.fields) !== JSON.stringify(actual.fields)) return `fields mismatch: expected ${JSON.stringify(exp.fields)}, got ${JSON.stringify(actual.fields)}`;
  try {
    const r2 = parseCsvLine(text);
    if (actual.ok && JSON.stringify(r2) !== JSON.stringify(actual.fields)) return "non-deterministic";
  } catch (e) { if (actual.ok) return "non-deterministic (threw second time)"; }
  return null;
}

let failures = 0;
const N = Number(process.argv[3] ?? 200000);
const core = ['"', ",", "\n", "\r", "a"];
function* exhaustive(len, prefix = "") {
  if (len === 0) { yield prefix; return; }
  for (const c of core) yield* exhaustive(len - 1, prefix + c);
}
let count = 0;
for (let len = 0; len <= 8; len++) {
  for (const t of exhaustive(len)) {
    count++;
    const f = run(t);
    if (f) { failures++; if (failures < 30) console.log("FAIL", JSON.stringify(t), f); }
  }
}
console.log("exhaustive cases:", count);
for (let n = 0; n < N; n++) {
  const len = Math.floor(rnd() * 24);
  let t = "";
  const alpha = rnd() < 0.7 ? weighted : alphabet;
  for (let k = 0; k < len; k++) t += alpha[Math.floor(rnd() * alpha.length)];
  const f = run(t);
  if (f) { failures++; if (failures < 30) console.log("FAIL", JSON.stringify(t), f); }
}
console.log("random cases:", N, "failures:", failures);
EOF
