  time(`all commas n=${n}`, ",".repeat(n));
  time(`giant quoted field n=${n}`, '"' + "a".repeat(n) + '"');
  time(`giant unquoted field n=${n}`, "a".repeat(n));
  time(`all "" in quotes n=${n}`, '"' + '""'.repeat(n / 2) + '"');
  time(`alternating ", n=${n}`, '",'.repeat(n / 2));
  time(`alternating "", n=${n}`, '"",'.repeat(n / 3 | 0));
  time(`quoted empty fields n=${n}`, Array(n / 5 | 0).fill('""').join(","));
  time(`a,a,a n=${n}`, Array(n / 2).fill("a").join(","));
  time(`unterminated giant n=${n}`, '"' + "a".repeat(n));
  time(`unterminated with commas n=${n}`, '"' + ",".repeat(n));
  time(`giant then bad char n=${n}`, '"' + "a".repeat(n) + '"x');
  time(`giant quoted with newlines n=${n}`, '"' + "\n".repeat(n) + '"');
  time(`giant quoted crlf n=${n}`, '"' + "\r\n".repeat(n / 2) + '"');
  time(`giant CR unquoted n=${n}`, "\r".repeat(n));
  time(`quote at very end n=${n}`, "a".repeat(n) + '"');
  time(`emoji giant n=${n}`, "😀".repeat(n / 2));
  time(`lone surrogates n=${n}`, "\uD800".repeat(n));
  time(`many escaped quote fields n=${n}`, Array(n / 6 | 0).fill('""""').join(","));
  time(`trailing lf giant n=${n}`, "a".repeat(n) + "\n");
  time(`trailing crlf giant quoted n=${n}`, '"' + "a".repeat(n) + '"\r\n');
  time(`quote-comma-quote runs n=${n}`, '"","'.repeat(n / 4 | 0));
}
